// Go: tầng ngoài đặt deadline, các tầng dưới dùng lại cùng ctx
ctx, cancel := context.WithTimeout(r.Context(), 800*time.Millisecond)
defer cancel()

// trước khi làm việc nặng, kiểm tra thời gian còn lại
if dl, ok := ctx.Deadline(); ok && time.Until(dl) < 50*time.Millisecond {
    return errors.New("không đủ thời gian, fail fast")
}

// gRPC tự gửi phần thời gian còn lại xuống server qua grpc-timeout
resp, err := inventoryClient.Reserve(ctx, req)
